-- Synthetic data only. Never load production schema/dumps into this fixture.
CREATE ROLE anon NOLOGIN;
CREATE ROLE authenticated NOLOGIN;
CREATE ROLE service_role NOLOGIN;
CREATE SCHEMA auth;
CREATE TABLE auth.users(id uuid PRIMARY KEY,email text,email_confirmed_at timestamptz,banned_until timestamptz,deleted_at timestamptz);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS
$$ SELECT coalesce(nullif(current_setting('request.jwt.claim.sub',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid $$;
CREATE FUNCTION auth.jwt() RETURNS jsonb LANGUAGE sql STABLE AS
$$ SELECT coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb $$;
GRANT USAGE ON SCHEMA public,auth TO anon,authenticated;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA auth TO anon,authenticated;
CREATE TABLE public.supervisor_id(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, uuid uuid, name text,email text,created_at timestamptz DEFAULT now());
CREATE TABLE public.registered_member(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,uuid uuid UNIQUE,email text,name text,phone_number text,student_id text,department text,generation text,is_manager boolean DEFAULT false,created_at timestamptz DEFAULT now());
CREATE TABLE public.allowed_user(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,email text UNIQUE,name text);
CREATE TABLE public.who_is_boss(id bigint PRIMARY KEY,uuid uuid,name text,created_at timestamptz DEFAULT now());
CREATE TABLE public.editor_5_donators(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name text,uuid uuid DEFAULT auth.uid(),date date,created_at timestamptz DEFAULT now());
CREATE TABLE public.editor_0_noti(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,text text,description text,is_noti boolean DEFAULT false,created_at timestamptz DEFAULT now());
CREATE TABLE public.editor_1_projects(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,project_name text,description text,created_at timestamptz DEFAULT now());
CREATE TABLE public.editor_2_studies(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,study_name text,outline text,created_at timestamptz DEFAULT now());
CREATE TABLE public.editor_3_study_timetable(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,study_name text,leader text,created_at timestamptz DEFAULT now());
CREATE TABLE public.editor_4_schedules(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,description text,start_date date,end_date date,created_at timestamptz DEFAULT now());
CREATE TABLE public.editor_6_events(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title text,description text,filenames jsonb,created_at timestamptz DEFAULT now());
DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['registered_member','allowed_user','supervisor_id','who_is_boss','editor_5_donators',
    'editor_0_noti','editor_1_projects','editor_2_studies','editor_3_study_timetable','editor_4_schedules','editor_6_events'] LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
    EXECUTE format('CREATE POLICY legacy_select ON public.%I FOR SELECT USING(true)',t);
    EXECUTE format('GRANT ALL ON public.%I TO authenticated',t);
  END LOOP;
END $$;
GRANT SELECT(email) ON public.registered_member,public.allowed_user TO anon;
GRANT SELECT ON public.editor_5_donators TO anon;
DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['editor_0_noti','editor_1_projects','editor_2_studies','editor_3_study_timetable','editor_4_schedules','editor_6_events'] LOOP
    EXECUTE format('CREATE POLICY synthetic_legacy_write ON public.%I FOR ALL TO authenticated USING(true) WITH CHECK(true)',t);
  END LOOP;
END $$;
REVOKE INSERT,UPDATE,DELETE,TRUNCATE ON public.supervisor_id FROM authenticated;
CREATE POLICY synthetic_signup ON public.registered_member FOR INSERT TO authenticated WITH CHECK
(uuid=auth.uid() AND email=auth.jwt()->>'email' AND EXISTS(SELECT FROM public.allowed_user a WHERE a.email=auth.jwt()->>'email'));
-- Reproduce permissive-OR plus independent restrictive-DML combination.
CREATE POLICY synthetic_broad_member ON public.registered_member FOR ALL TO authenticated USING(true) WITH CHECK(true);
CREATE POLICY synthetic_signup_guard ON public.registered_member AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK
(uuid=auth.uid() AND email=auth.jwt()->>'email' AND EXISTS(SELECT FROM public.allowed_user a WHERE a.email=auth.jwt()->>'email'));
CREATE POLICY synthetic_broad_approval ON public.allowed_user FOR ALL TO authenticated USING(true) WITH CHECK(true);
CREATE POLICY synthetic_approval_insert ON public.allowed_user AS RESTRICTIVE FOR INSERT TO authenticated
WITH CHECK(EXISTS(SELECT FROM public.supervisor_id WHERE uuid=auth.uid()));
CREATE POLICY synthetic_approval_update ON public.allowed_user AS RESTRICTIVE FOR UPDATE TO authenticated
USING(EXISTS(SELECT FROM public.supervisor_id WHERE uuid=auth.uid())) WITH CHECK(EXISTS(SELECT FROM public.supervisor_id WHERE uuid=auth.uid()));
CREATE POLICY synthetic_approval_delete ON public.allowed_user AS RESTRICTIVE FOR DELETE TO authenticated
USING(EXISTS(SELECT FROM public.supervisor_id WHERE uuid=auth.uid()));
GRANT USAGE ON ALL SEQUENCES IN SCHEMA public TO authenticated;
