-- Fake legacy write policies are intentionally stricter than table grants.
CREATE POLICY synthetic_donor_write ON public.editor_5_donators FOR ALL TO authenticated
USING(EXISTS(SELECT FROM public.supervisor_id WHERE uuid=auth.uid()))
WITH CHECK(EXISTS(SELECT FROM public.supervisor_id WHERE uuid=auth.uid()));
